import hashlib,os,pathlib,re,stat
def reclaim_stale(directory,manifest):
    root=pathlib.Path(directory)
    try:info=root.lstat()
    except OSError as error:raise ValueError('private approved directory required') from error
    if not root.is_absolute() or root.resolve()!=root or not stat.S_ISDIR(info.st_mode) or info.st_uid!=os.geteuid() or info.st_mode&0o077:raise ValueError('owned private non-symlink directory required')
    if not isinstance(manifest,list):raise ValueError('explicit manifest list required')
    names=set();removals=[]
    for row in manifest:
        if not isinstance(row,dict) or set(row)!={'name','size','sha256','state'}:raise ValueError('exact manifest fields required')
        name=row['name'];size=row['size'];digest=row['sha256']
        if not isinstance(name,str) or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.-]{0,79}',name) or name in names or row['state'] not in ('active','stale') or not isinstance(size,int) or isinstance(size,bool) or not 0<=size<=67108864 or not isinstance(digest,str) or not re.fullmatch(r'[0-9a-f]{64}',digest):raise ValueError('invalid/duplicate manifest entry')
        names.add(name);path=root/name
        try:
            info=path.lstat()
            if not stat.S_ISREG(info.st_mode) or info.st_uid!=os.geteuid() or info.st_nlink!=1 or info.st_size!=size:raise ValueError('approved regular single-link file changed')
            with path.open('rb') as stream:actual=hashlib.file_digest(stream,'sha256').hexdigest()
        except OSError as error:raise ValueError('approved file unavailable') from error
        if actual!=digest:raise ValueError('approved file digest changed')
        if row['state']=='stale':removals.append((path,size))
    for path,size in removals:path.unlink()
    return sum(size for path,size in removals)
